import json,numpy as np
W=Path(__file__).resolve().parent;a=json.loads((W/'indent_result.json').read_text());b=json.loads((W/'indent_refined_result.json').read_text());x=np.load(W/'indent_trajectory.npz');y=np.load(W/'indent_refined_trajectory.npz');assert np.array_equal(x['t'],y['t']);pe=float(np.linalg.norm(x['x']-y['x'],axis=2).max());ve=float(np.linalg.norm(x['v']-y['v'],axis=2).max());fe=max(float(np.linalg.norm(u-v)/max(np.linalg.norm(v),1e-6)) for u,v in zip(x['reaction'],y['reaction']));me=max(float(np.linalg.norm(u-v)/max(np.linalg.norm(v),1e-8)) for u,v in zip(x['moment'],y['moment']));passed=bool(a['component_passed'] and b['component_passed'] and pe<=1e-4 and ve<=.005 and fe<=.05 and me<=.05);out={'scope':'Exact-original-CAD prescribed nonfracturing contact on intact FEM; node-collocated surface contact, NOT new cut-assembly/native robot/full separation qualification','both_loaded_and_unloaded':bool(a['loaded'] and a['unloaded'] and b['loaded'] and b['unloaded']),'position_max_error_m':pe,'velocity_max_error_m_s':ve,'reaction_max_relative_or_floor_error':fe,'moment_max_relative_or_floor_error':me,'peak_reaction_N':max(r['force_norm_N'] for r in a['rows']),'late_reaction_max_N':max(r['force_norm_N'] for r in a['rows'] if r['sim_s']>=.04),'maximum_CAD_penetration_m':max(r['maximum_CAD_penetration_m'] for r in a['rows']),'maximum_discrete_force_balance_error_N':max(r['max_discrete_force_balance_error_N'] for r in a['rows']),'passed':passed};(W/'indent_qualification.json').write_text(json.dumps(out,indent=2));print(json.dumps(out,indent=2));assert passed
